use crate::cards;
use std::collections::HashMap;

#[derive(Clone)]
pub struct Slot {
    pub label: String,
    pub reply: String,
}

pub fn rib_b() -> HashMap<i64, Slot> {
    let mut slots = HashMap::new();
    for row in cards::load() {
        slots.insert(
            row.wire,
            Slot {
                label: row.label,
                reply: row.reply,
            },
        );
    }
    slots
}

pub fn serves(slots: &HashMap<i64, Slot>, row: &cards::Row) -> bool {
    slots
        .get(&row.wire)
        .map(|slot| slot.label == row.label && slot.reply == row.reply)
        .unwrap_or(false)
}

pub fn tap(n: i64) -> i32 {
    let slots = rib_b();
    let reply = slots
        .get(&n)
        .map(|slot| slot.reply.as_str())
        .unwrap_or("fallthrough");
    println!("{{\"wire\":{},\"reply\":\"{}\"}}", n, reply);
    0
}
EOF
